lines=['# AI source audit: S36–S79','', 'Prepared 6 November 2026 by the AI agent named `saif`. This is not work performed by the human Saif Shahzad and is not independent human screening. Human screening cells and canonical data were not edited.','', '## Scope and limits','', 'All 44 assigned records were inspected for auditability. 20 had targeted full-text passages checked (10 local extracted texts, 10 remote primary full texts); 8 had abstract-only corroboration; 16 had no accessible full text after primary-link attempts. Targeted checks are not exhaustive re-reading or an independent rescore of all 440 quality items. No study can be labelled fully human-verified from this audit. Access failures do not establish nonexistence or inaccuracy. Metadata, paper claims and actual code execution are different evidence levels.','', 'The existing master records and original JSONL extracts were compared; original record locations are listed below. QA vectors shown are existing values, not a new endorsement. Original AI-generated text is never treated as corroborating source evidence.','', '## Actionable findings','', '1. **S36:** separate bootstrap performance tests from Wilcoxon explanation tests on 100 instances.','2. **S72:** correct the claim that repetitions are not detailed; 20 runs/20 seeds are explicit. Score change requires adjudication.','3. **S73:** record the explicit repository URL from footnote 9; the repository itself was not tested.','4. **S67:** replace the erroneous composite-stability note with the actual pairwise top-10 overlap protocol, preserving the score pending review.','5. **S78:** add the authors’ limitations and the source’s internal numeric inconsistencies. Keep disputed source numbers visible rather than silently repairing the source.','6. **S43:** explicitly discuss its tree-only split-frequency screen. Its target is global ranking flips across retrained models, not instance-level explanation change under prediction-preserving input perturbations. The proposed research gap should be narrowed to that difference. The screen’s validation uses precision/recall, not AUROC. Do not claim tree-only diagnostics do not exist.','7. **S49 and S75:** distinguish cross-method disagreement from within-method variation across models; reconcile borderline inclusion with EC3.','8. **S77:** retain the out-of-sample condition; the paper reports an in-sample counterexample.','', '## Per-study coverage','']
for e in inv:
 r=e['master'];n=int(r['sid'][1:]);where,note=notes[n]
 status='Targeted full text' if n in full else 'Abstract only; full text unverified' if n in abstract else 'Full text unavailable; source claims unverified'
 url=urls.get(n, ('https://doi.org/'+r['doi']) if r.get('doi') else '')
 o=e['origin'];orig=f"{o.get('file','unknown')}:{o.get('line','?')} (uid `{r['uid']}`)"
 lines += [f"### {r['sid']}: {r['title']}",'',f'- Status: **{status}**.',f'- Source: {where}. '+(f'[Primary source]({url}).' if url else ''),f'- Original record: `{orig}`.',f'- Finding: {note}',f"- Existing QA Q1–Q10: `{json.dumps(r['qa'])}`. Existing notes: {r['qa_notes']}",'- QA audit limit: no full independent item-by-item rescore. Only specific evidence findings above can support a revision.','']
lines+=['## Safe integration','', 'Suggested field-level corrections are in `work/audit_saif/proposed_patches.json`. They are proposals, not applied changes. Apply factual corrections to original JSONL extraction data and its shipped mirror, then rebuild dependent master records/tables; preserve human workbook inputs. Keep the human contribution and dual-screening status pending until the named students actually complete them.','', 'Versions matter: S46 v2 was released 31 October after the original 24–25 October search. This audit checked v1 for original extraction and reports newer metadata separately. Other online sources may have changed since extraction; preserve source/version dates when integrating changes.']
(root/'work/audit_saif.md').write_text('\n'.join(lines)+'\n')
patches=[]
def add(sid,field,new,evidence,kind='factual correction'):
 e=next(e for e in inv if e['sid']==sid);o=e['origin'];r=o['record']
 patches.append(dict(sid=sid,uid=e['uid'],origin_file=o['file'],origin_line=o['line'],field=field,old=r[field],new=new,evidence=evidence,source=urls.get(int(sid[1:]),''),kind=kind,applied=False))
add('S36','evaluation','Jaccard similarity of top-10 features and Rank Agreement vs balanced reference; Mann-Whitney U tests on performance distributions from 100 test-set bootstrap samples (§3.1), and Wilcoxon signed-rank tests on explanation-consistency metrics for 100 test instances (§3.2.1).','Publisher §3.1 uses 100 bootstrap samples for performance; §3.2.1 uses 100 test instances for explanation comparisons.')
add('S72','qa_notes','Q2/Q3 brief; Q5 stability score loosely defined; Q6 small experiments; Q10 20 runs with 20 different random seeds explicitly reported (pp.4–5); reconsider the existing 0.5 score.','Local N029.txt p.4 specifies 20 runs with 20 different seeds and p.5 gives T=20.')
add('S72','evaluation','Stability score over 20 runs with 20 different random seeds (pp.4–5), local fidelity, human prediction accuracy from explanations; comparison with ALIME.','Local N029.txt pp.4–5.')
